import{_ as p,a0 as o,w as r,s as b,ao as i,I as s,x as u,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"Ubuntu 13.10 之于 Ubuntu 13.04，给我一个升级的理由 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 13.10 之于 Ubuntu 13.04，给我一个升级的理由 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 13.10 之于 Ubuntu 13.04，给我一个升级的理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 13.10 之于 Ubuntu 13.04，给我一个升级的理由 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade","title":"Ubuntu 13.10 之于 Ubuntu 13.04，给我一个升级的理由","tag":"201310","desc":""},"relativePath":"201310/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade.md","filePath":"[post].md"}'),l={name:"201310/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade.md"};function U(d,t,m,T,f,g){const n=o("Link");return r(),b("div",null,[t[11]||(t[11]=i('<h1 id="ubuntu-13-10-之于-ubuntu-13-04-给我一个升级的理由" tabindex="-1">Ubuntu 13.10 之于 Ubuntu 13.04，给我一个升级的理由 <a class="header-anchor" href="#ubuntu-13-10-之于-ubuntu-13-04-给我一个升级的理由" aria-label="Permalink to “Ubuntu 13.10 之于 Ubuntu 13.04，给我一个升级的理由”">​</a></h1><p><strong>Ubuntu 13.10(Saucy Salamander)</strong> 将于10月17日发布，但是这个由Canonical开发的操作系统的用户就有疑问了，新的版本似乎并没有添加多少新的特性，有鉴于此，为什么他们要更新呢？</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade-389846-2.jpg" alt="img"></p><p>Canonical的主要精力花费在提升品质和改进已有的功能上，而不是巨大的变化。这就意味这最近的两个版本不会有很大的不同，至少在表面上看起来是这样的。</p><p>Ubuntu 13.04(Raring Ringtail)，相较而言，令人乏味，但是人们并没有意识到Ubuntu每一次发布的背后都意味着需要完成大量的工作，即使初看起来没有太大的变动。</p><p>那么，对于普通用户来说如果新的版本并没有显著的变更，为什么还要升级到 Ubuntu 13.10呢？事实上,初看起来似乎几乎没什么变化，然而许多东西已经升级改善，总会变得更好的(多数情况下是这样)。</p><p>当然，最重要的一点，这次的发布所带的新的linux内核3.11.x，是目前为止最新的稳定版本。新内核版本支持更多的设备和硬件组件，更好的电源管理性能，还有很多很多其他方面的改善。</p><p>另外，GNOME也升级了。Canonical支持Unity桌面环境，但是仍然使用许多GNOME的软件包。Ubuntu 13.10 (Saucy Salamander) 自带有来自3.8 分支的应用，这些应用都非常棒，对偏好Ubuntu GNOME的用户来说尤其如此。</p><p>相对于之前的Lens功能，Smart Scopes仍然有大的改善：更好的集成并且提供更多的定向解答。</p><p>安全性设置全面更新了，现在用户可以对系统产生的流量有更多的控制。用户可以停止自己的PC或者laptop和Canonical服务器之间的通信。</p><p>Ubuntu 13.10 也为新的软件包格式奠定了基础。迄今，所有Ubuntu应用都是以deb格式提供的。不过用户需要事先安装相关依赖项，或者用户选择自己单独安装。</p><p>而使用新的Click包类型，所有的依赖项都可以在包本身内部获得，这就意味着, 只要应用开发者使用的是ubuntu SDK, 用户就不会再碰到任何与当前使用版本不兼容的软件包。</p><p>最后，Unity进行了大量改进，理应比任何以前的ubuntu版本工作得更出色。</p><p>如果这些缘由仍然不足以说服你升级ubuntu，那就只有等待Ubuntu 14.04 LTS的发行了。不过不保证新的版本会看起来跟Ubuntu 13.10有多么大的不同。</p><hr>',15)),s("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://news.softpedia.com/news/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade-389846.shtml"},{default:a(()=>[...t[0]||(t[0]=[u("http://news.softpedia.com/news/Ubuntu-13-10-vs-Ubuntu-13-04-Reasons-to-Upgrade-389846.shtml",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[2]||(t[2]=[u("LCTT",-1)])]),_:1}),t[5]||(t[5]=u(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:a(()=>[...t[3]||(t[3]=[u("Linux中国",-1)])]),_:1}),t[6]||(t[6]=u(" 荣誉推出",-1))]),s("p",null,[t[9]||(t[9]=u("译者：",-1)),e(n,{href:"https://github.com/l3b2w1"},{default:a(()=>[...t[7]||(t[7]=[u("l3b2w1",-1)])]),_:1}),t[10]||(t[10]=u(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[u("wxy",-1)])]),_:1})])])}const w=p(l,[["render",U]]);export{S as __pageData,w as default};
